'use client';

import { useEffect, useRef, useState, type ChangeEvent, type ReactNode } from 'react';
import {
  ArrowRight, Bell, BookOpen, CalendarDays, Check, CheckCircle2, ClipboardCheck,
  Clock3, Copy, Dices, Download, ExternalLink, FileText, Grid2X2, Home as HomeIcon,
  Link2, Paperclip,
  LockKeyhole, LogOut, MessageCircle, Palette, Plus, RotateCcw, Save, Search,
  Send, Settings2, ShieldCheck, Trash2, Upload, Users, X,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';

type Role = 'teacher' | 'family' | 'admin' | 'screen';
type TeacherView = 'home' | 'journal' | 'homework' | 'calendar' | 'class' | 'tools' | 'settings';
type FamilyView = 'journal' | 'homework' | 'calendar' | 'me';
type AdminView = 'overview' | 'settings';
type Student = { number: number; name: string };
type HomeworkAttachment = { name: string; url: string };
type Journal = { id: string; date: string; homework: string; bring: string; notice: string; published: boolean; readBy: boolean; reply: string; readByStudents?: number[]; replies?: Record<string, string> };
type Homework = { id: string; subject: string; title: string; due: string; publishOn?: string; attachments?: HomeworkAttachment[]; screenReported: number[]; familyDone: number[]; teacherConfirmed: number[] };
type CalendarEvent = { id: string; date: string; title: string; type: '活動' | '考試' | '提醒' };
type AppData = { className: string; inviteCode: string; teacherUsername: string; teacherPassword: string; teacherPasswordHash: string; familyUsername: string; familyPasswordHash: string; adminUsername: string; adminPasswordHash: string; classroomUrl: string; classroomCourseName: string; classroomConnected: boolean; students: Student[]; journals: Journal[]; homeworks: Homework[]; events: CalendarEvent[]; linkedChild: number | null; theme: 'coral' | 'blue' | 'mint'; grid: boolean };
type SyncStatus = 'loading' | 'database' | 'saving' | 'local';

const emptyData: AppData = { className: '', inviteCode: '', teacherUsername: '', teacherPassword: '', teacherPasswordHash: '', familyUsername: '', familyPasswordHash: '', adminUsername: '', adminPasswordHash: '', classroomUrl: '', classroomCourseName: '', classroomConnected: false, students: [], journals: [], homeworks: [], events: [], linkedChild: null, theme: 'coral', grid: true };
const storageKey = 'class-little-notebook-prototype-v5';
const sessionKey = 'class-little-notebook-session-v1';
function getToday() { const now = new Date(); const year = now.getFullYear(); const month = String(now.getMonth() + 1).padStart(2, '0'); const day = String(now.getDate()).padStart(2, '0'); return `${year}-${month}-${day}`; }
const today = getToday();

function cn(...items: Array<string | false | undefined | null>) { return items.filter(Boolean).join(' '); }
function makeId(prefix: string) { return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`; }
async function hashSecret(secret: string) { const bytes = new TextEncoder().encode(secret); const digest = await crypto.subtle.digest('SHA-256', bytes); return Array.from(new Uint8Array(digest)).map((value) => value.toString(16).padStart(2, '0')).join(''); }
function statusLabel(work: Homework, studentNumber?: number) { if (studentNumber && work.teacherConfirmed.includes(studentNumber)) return '教師已確認'; if (studentNumber && (work.screenReported.includes(studentNumber) || work.familyDone.includes(studentNumber))) return '待教師核對'; return '未登記'; }
function homeworkIsPublished(work: Homework, date = getToday()) { return !work.publishOn || work.publishOn <= date; }
function journalReadBy(journal: Journal, studentNumber: number) { return journal.readByStudents?.includes(studentNumber) || journal.readBy; }
function journalReply(journal: Journal, studentNumber: number) { return journal.replies?.[String(studentNumber)] || journal.reply; }
function downloadFile(filename: string, content: string, type = 'application/json') { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }
function csvEscape(value: string | number) { return `"${String(value).replaceAll('"', '""')}"`; }
function Pill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'orange' | 'gray' | 'blue' }) { return <Badge className={cn('simple-pill', `simple-pill-${tone}`)}>{children}</Badge>; }

function NotebookMark() {
  return <svg viewBox="0 0 40 40" aria-hidden="true" focusable="false">
    <path d="M7.5 8.5h17.8c3.8 0 6.7 2.4 7.2 5.8v17.2c-.9-2.4-3.2-3.9-6.1-3.9H7.5V8.5Z" />
    <path d="M7.5 8.5v19.1h18.9c2.9 0 5.2 1.5 6.1 3.9" />
    <path d="M12 14h8M12 18.5h10M12 23h7" />
    <path d="M25.3 8.5v18.9" />
  </svg>;
}

function Logo() { return <div className="simple-logo"><span className="brand-mark"><NotebookMark /></span><div><strong>班級小本本</strong><small>班級聯絡簿</small></div></div>; }

function Login({ data, updateData, onEnter }: { data: AppData; updateData: (next: AppData) => void; onEnter: (role: 'teacher' | 'family' | 'admin', remember: boolean) => void }) {
  const [mode, setMode] = useState<'login' | 'register' | 'forgot'>('login');
  const [registerRole, setRegisterRole] = useState<'teacher' | 'family' | 'admin'>('teacher');
  const [username, setUsername] = useState(''); const [secret, setSecret] = useState(''); const [invite, setInvite] = useState(''); const [remember, setRemember] = useState(true); const [error, setError] = useState('');
  const firstTeacher = !data.teacherUsername && !data.teacherPasswordHash && !data.teacherPassword; const firstFamily = !data.familyUsername && !data.familyPasswordHash; const firstAdmin = !data.adminUsername && !data.adminPasswordHash;
  const reset = (nextMode: 'login' | 'register' | 'forgot') => { setMode(nextMode); setSecret(''); setInvite(''); setError(''); if (nextMode === 'register') setUsername(''); };
  const login = async () => { const name = username.trim().toLowerCase(); const password = secret.trim(); if (name.length < 2 || password.length < 4) { setError('請輸入有效的帳號與密碼。'); return; } const hash = await hashSecret(password); if (data.teacherUsername.toLowerCase() === name && ((data.teacherPasswordHash && data.teacherPasswordHash === hash) || (!data.teacherPasswordHash && data.teacherPassword === password))) { onEnter('teacher', remember); return; } if (data.familyUsername.toLowerCase() === name && data.familyPasswordHash === hash) { onEnter('family', remember); return; } if (data.adminUsername.toLowerCase() === name && data.adminPasswordHash === hash) { onEnter('admin', remember); return; } setError('帳號或密碼不正確。'); };
  const register = async () => { const name = username.trim(); const password = secret.trim(); if (name.length < 2) { setError('帳號至少需要 2 個字元。'); return; } if (password.length < 4) { setError('密碼至少需要 4 個字元。'); return; } const hash = await hashSecret(password); if (registerRole === 'teacher') { if (!firstTeacher) { setError('教師帳號已存在，請直接登入。'); return; } updateData({ ...data, teacherUsername: name, teacherPassword: '', teacherPasswordHash: hash }); onEnter('teacher', remember); return; } if (registerRole === 'admin') { if (!firstAdmin) { setError('管理員帳號已存在，請直接登入。'); return; } updateData({ ...data, adminUsername: name, adminPasswordHash: hash }); onEnter('admin', remember); return; } if (!data.inviteCode || !data.students.length) { setError('家長註冊需要教師先建立班級與學生名單。'); return; } if (invite.trim().toUpperCase() !== data.inviteCode.toUpperCase()) { setError('班級邀請碼不正確。'); return; } if (!firstFamily) { setError('家長帳號已存在，請直接登入。'); return; } updateData({ ...data, familyUsername: name, familyPasswordHash: hash, linkedChild: data.linkedChild || data.students[0].number }); onEnter('family', remember); };
  const accountReady = Boolean(data.teacherPasswordHash || data.teacherPassword || data.familyPasswordHash || data.adminPasswordHash);
  return <main className="login-page"><section className="login-panel"><Logo /><div className="login-copy"><span>{mode === 'login' ? '帳號登入' : mode === 'register' ? '建立帳號' : '帳號協助'}</span><h1>{mode === 'login' ? '登入班級小本本' : mode === 'register' ? '註冊帳號' : '忘記密碼'}</h1><p>{mode === 'login' ? '輸入帳號與密碼即可進入對應工作區；學生只在教室大螢幕點選座號。' : mode === 'register' ? '先選擇身份，再建立對應的帳號。' : '帳號與班級資料會保存於雲端資料庫；忘記密碼時請由管理員協助處理。'}</p></div>{mode === 'login' && <><label className="login-field">帳號<input value={username} onChange={(event) => { setUsername(event.target.value); setError(''); }} placeholder="教師、家長或管理員帳號" autoComplete="username" /></label><label className="login-field">密碼<input type="password" value={secret} onChange={(event) => { setSecret(event.target.value); setError(''); }} placeholder="輸入密碼" autoComplete="current-password" onKeyDown={(event) => { if (event.key === 'Enter') void login(); }} /></label><label className="remember-login"><input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)} /> 在這台裝置保持登入</label>{!accountReady && <p className="inline-note">還沒有帳號？請先註冊。</p>}<Button className="full-button" onClick={() => void login()}>登入 <ArrowRight size={16} /></Button><div className="auth-links"><button onClick={() => reset('forgot')}>忘記密碼</button><button onClick={() => reset('register')}>註冊帳號</button></div></>}{mode === 'register' && <><div className="register-roles"><button className={cn(registerRole === 'teacher' && 'selected')} onClick={() => setRegisterRole('teacher')}><Users size={17} /><span><strong>教師</strong><small>管理班級與作業</small></span></button><button className={cn(registerRole === 'family' && 'selected')} onClick={() => setRegisterRole('family')}><HomeIcon size={17} /><span><strong>家長</strong><small>查看聯絡簿與孩子作業</small></span></button><button className={cn(registerRole === 'admin' && 'selected')} onClick={() => setRegisterRole('admin')}><ShieldCheck size={17} /><span><strong>系統管理員</strong><small>維護資料與系統狀態</small></span></button></div><label className="login-field">帳號<input value={username} onChange={(event) => { setUsername(event.target.value); setError(''); }} placeholder="設定帳號" autoComplete="username" /></label>{registerRole === 'family' && <label className="login-field">班級邀請碼<input value={invite} onChange={(event) => { setInvite(event.target.value); setError(''); }} placeholder="例如 CLASS-7F2P9" /></label>}<label className="login-field">設定密碼<input type="password" value={secret} onChange={(event) => { setSecret(event.target.value); setError(''); }} placeholder="至少 4 個字元" autoComplete="new-password" onKeyDown={(event) => { if (event.key === 'Enter') void register(); }} /></label><Button className="full-button" onClick={() => void register()}>建立{registerRole === 'teacher' ? '教師' : registerRole === 'family' ? '家長' : '管理員'}帳號 <ArrowRight size={16} /></Button><div className="auth-links"><button onClick={() => reset('login')}>返回登入</button></div></>}{mode === 'forgot' && <><section className="forgot-card"><LockKeyhole size={24} /><strong>需要協助登入？</strong><p>請使用系統管理員提供的備份檔還原帳號，或在同一台裝置請管理員協助處理。帳號資料現在會保存於雲端資料庫。</p></section><Button variant="outline" className="full-button" onClick={() => reset('login')}>返回登入</Button></>}{error && <p className="login-error">{error}</p>}<small className="login-note">教師、家長與管理員使用帳密登入；學生不建立登入帳號。</small></section></main>;
}

function Topbar({ role, onRole, onLogout, syncStatus }: { role: Role; onRole: (role: Role) => void; onLogout: () => void; syncStatus: SyncStatus }) {
  const syncLabel = syncStatus === 'database' ? '已同步資料庫' : syncStatus === 'saving' ? '保存中…' : syncStatus === 'loading' ? '載入資料…' : '本機備援';
  return <header className="simple-topbar"><Logo /><div className="top-role">{role === 'teacher' && <><button className="active">教師端</button><button onClick={() => onRole('screen')}>大螢幕</button></>}{role === 'admin' && <button className="active">管理員端</button>}{role === 'family' && <button className="active">家長端</button>}{role === 'screen' && <button className="active">大螢幕</button>}</div><div className="top-user"><span className={cn('sync-indicator', syncStatus === 'local' && 'offline')} title={syncStatus === 'local' ? '資料庫暫時無法連線，變更會保存在本機' : '班級資料會保存到雲端資料庫'}><span className="sync-dot" />{syncLabel}</span><span className="user-avatar">{role === 'family' ? '家' : role === 'admin' ? '管' : '師'}</span><span>{role === 'family' ? '家長帳號' : role === 'admin' ? '系統管理員' : '教師帳號'}</span>{role !== 'screen' && <button aria-label="登出" onClick={onLogout}><LogOut size={15} /></button>}{role === 'screen' && <Button size="sm" variant="outline" onClick={() => onRole('teacher')}><X size={14} /> 離開</Button>}</div></header>;
}

function Sidebar({ role, teacherView, familyView, adminView, setTeacherView, setFamilyView, setAdminView, data }: { role: Role; teacherView: TeacherView; familyView: FamilyView; adminView: AdminView; setTeacherView: (view: TeacherView) => void; setFamilyView: (view: FamilyView) => void; setAdminView: (view: AdminView) => void; data: AppData }) {
  if (role === 'screen') return null;
  const teacherItems: Array<[TeacherView, string, ReactNode]> = [['home', '總覽', <ClipboardCheck size={17} key="home" />], ['journal', '聯絡簿', <BookOpen size={17} key="journal" />], ['homework', '作業', <CheckCircle2 size={17} key="homework" />], ['calendar', '行事曆', <CalendarDays size={17} key="calendar" />], ['class', '班級', <Users size={17} key="class" />], ['tools', '教學工具', <Grid2X2 size={17} key="tools" />], ['settings', '設定', <Settings2 size={17} key="settings" />]];
  const familyItems: Array<[FamilyView, string, ReactNode]> = [['journal', '聯絡簿', <BookOpen size={17} key="journal" />], ['homework', '作業', <CheckCircle2 size={17} key="homework" />], ['calendar', '行事曆', <CalendarDays size={17} key="calendar" />], ['me', '我的', <Settings2 size={17} key="me" />]];
  const adminItems: Array<[AdminView, string, ReactNode]> = [['overview', '系統總覽', <ShieldCheck size={17} key="overview" />], ['settings', '資料管理', <Settings2 size={17} key="settings" />]];
  return <aside className="simple-sidebar"><div className="sidebar-context"><span className="context-label">{role === 'teacher' ? '目前班級' : role === 'admin' ? '管理範圍' : '已連結孩子'}</span><strong>{role === 'teacher' ? data.className || '尚未建立班級' : role === 'admin' ? '目前瀏覽器工作區' : data.linkedChild ? data.students.find((student) => student.number === data.linkedChild)?.name || '孩子' : '尚未連結孩子'}</strong><small>{role === 'teacher' ? `${data.students.length} 位學生` : role === 'admin' ? `${data.students.length} 位學生・${data.homeworks.length} 項作業` : data.className || '輸入邀請碼即可開始'}</small></div><nav>{role === 'teacher' ? teacherItems.map(([id, label, icon]) => <button key={id} className={cn(teacherView === id && 'active')} onClick={() => setTeacherView(id)}>{icon}<span>{label}</span>{id === 'homework' && data.homeworks.length > 0 && <i>{data.homeworks.length}</i>}</button>) : role === 'admin' ? adminItems.map(([id, label, icon]) => <button key={id} className={cn(adminView === id && 'active')} onClick={() => setAdminView(id)}>{icon}<span>{label}</span></button>) : familyItems.map(([id, label, icon]) => <button key={id} className={cn(familyView === id && 'active')} onClick={() => setFamilyView(id)}>{icon}<span>{label}</span></button>)}</nav><div className="sidebar-help"><Bell size={15} /><span>{role === 'teacher' ? '先建立班級，再開始發布內容。' : role === 'admin' ? '管理員可協助檢查資料與備份。' : '聯絡簿由老師發布，家長可以回覆。'}</span></div></aside>;
}

function EmptyState({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function TeacherHome({ data, updateData, go }: { data: AppData; updateData: (next: AppData) => void; go: (view: TeacherView) => void }) {
  const [className, setClassName] = useState(data.className); const [classError, setClassError] = useState('');
  const createClass = () => { const name = className.trim(); if (!name) { setClassError('請先輸入班級名稱。'); return; } setClassError(''); updateData({ ...data, className: name, inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); };
  if (!data.className) return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教師端・第一次使用</span><h1>先建立你的班級</h1><p>完成這一步後，就能新增學生、發布聯絡簿與管理作業。</p></div></div><section className="simple-card setup-card"><div className="step-number">1</div><div className="setup-copy"><h2>班級名稱</h2><p>例如：五年三班。這個名稱會顯示給家長。</p><div className="input-row"><input value={className} onChange={(event) => { setClassName(event.target.value); setClassError(''); }} placeholder="輸入班級名稱" /><Button onClick={createClass}>建立班級 <ArrowRight size={15} /></Button></div>{classError && <p className="form-error">{classError}</p>}</div></section></div>;
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教師端・{today}</span><h1>{data.className} <span className="muted-title">工作區</span></h1><p>從這裡建立今天要讓家庭知道的內容。</p></div><Button onClick={() => go('journal')}><Plus size={16} /> 建立今日聯絡簿</Button></div><div className="quick-grid"><button onClick={() => go('class')}><span className="quick-icon peach"><Users size={19} /></span><strong>新增學生</strong><small>{data.students.length ? `${data.students.length} 位學生` : '目前還沒有學生'}</small></button><button onClick={() => go('journal')}><span className="quick-icon green"><BookOpen size={19} /></span><strong>發布聯絡簿</strong><small>{data.journals.filter((journal) => journal.date === today && journal.published).length ? '今日已有發布內容' : '今天尚未發布'}</small></button><button onClick={() => go('homework')}><span className="quick-icon blue"><CheckCircle2 size={19} /></span><strong>新增作業</strong><small>{data.homeworks.length ? `${data.homeworks.length} 項作業` : '目前還沒有作業'}</small></button></div><div className="two-column"><section className="simple-card"><div className="card-heading"><div><span className="kicker">今天</span><h2>聯絡簿狀態</h2></div><Pill tone={data.journals.some((journal) => journal.date === today && journal.published) ? 'green' : 'gray'}>{data.journals.some((journal) => journal.date === today && journal.published) ? '已發布' : '尚未發布'}</Pill></div>{data.journals.length ? <div className="compact-list">{data.journals.slice().reverse().slice(0, 3).map((journal) => <div key={journal.id}><span>{journal.date}</span><strong>{journal.homework || journal.notice || '聯絡簿內容'}</strong><Pill tone={journal.published ? 'green' : 'gray'}>{journal.published ? '已發布' : '草稿'}</Pill></div>)}</div> : <EmptyState icon={<BookOpen size={20} />} title="還沒有聯絡簿" text="新增一篇，讓家長知道今天的作業與提醒。" action={<Button variant="outline" size="sm" onClick={() => go('journal')}>新增聯絡簿</Button>} />}</section><section className="simple-card"><div className="card-heading"><div><span className="kicker">班級</span><h2>作業追蹤</h2></div><Button variant="ghost" size="sm" onClick={() => go('homework')}>查看 <ArrowRight size={14} /></Button></div>{data.homeworks.length ? <div className="compact-list">{data.homeworks.slice().reverse().slice(0, 4).map((work) => <div key={work.id}><span className="subject-tag">{work.subject || '作業'}</span><strong>{work.title}</strong><small>{new Set([...work.screenReported, ...work.familyDone]).size} 人有回報</small></div>)}</div> : <EmptyState icon={<CheckCircle2 size={20} />} title="還沒有作業" text="建立作業後，學生就能在教室大螢幕登記。" action={<Button variant="outline" size="sm" onClick={() => go('homework')}>新增作業</Button>} />}</section></div></div>;
}

function JournalEditor({ data, updateData, selectedDate, existing }: { data: AppData; updateData: (next: AppData) => void; selectedDate: string; existing?: Journal }) {
  const [homework, setHomework] = useState(existing?.homework || '');
  const [bring, setBring] = useState(existing?.bring || '');
  const [notice, setNotice] = useState(existing?.notice || '');
  const save = (published: boolean) => { const journal: Journal = { id: existing?.id || makeId('journal'), date: selectedDate, homework: homework.trim(), bring: bring.trim(), notice: notice.trim(), published, readBy: existing?.readBy || false, reply: existing?.reply || '', readByStudents: existing?.readByStudents || [], replies: existing?.replies || {} }; updateData({ ...data, journals: [...data.journals.filter((item) => item.date !== selectedDate), journal] }); };
  const replies = existing?.replies ? Object.entries(existing.replies).filter(([, value]) => value.trim()) : [];
  return <><section className="simple-card form-card"><label>今天的作業<textarea value={homework} onChange={(event) => setHomework(event.target.value)} placeholder="例如：數學課本第 42–43 頁；國語朗讀第 3 課。" /></label><label>明天要帶什麼<textarea value={bring} onChange={(event) => setBring(event.target.value)} placeholder="例如：自然觀察紀錄單、水壺。" /></label><label>班級提醒<textarea value={notice} onChange={(event) => setNotice(event.target.value)} placeholder="例如：週三進行校外教學行前說明。" /></label><div className="form-actions"><span>內容會顯示在家長端</span><div><Button variant="outline" onClick={() => save(false)}><Save size={14} /> 儲存草稿</Button><Button onClick={() => save(true)}>發布給家長 <ExternalLink size={15} /></Button></div></div></section>{replies.length > 0 && <section className="simple-card reply-preview"><span className="kicker">家長回覆</span>{replies.map(([number, value]) => <p className="reply-line" key={number}><strong>{data.students.find((student) => String(student.number) === number)?.name || `${number} 號家長`}</strong>{value}</p>)}</section>}</>;
}

function TeacherJournal({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [selectedDate, setSelectedDate] = useState(today);
  const existing = data.journals.find((journal) => journal.date === selectedDate);
  const history = data.journals.slice().sort((a, b) => b.date.localeCompare(a.date));
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">聯絡簿</span><h1>{selectedDate === today ? '今天要讓家庭知道什麼？' : `${selectedDate} 聯絡簿`}</h1><p>可回看過往日期，儲存草稿後再發布。</p></div><Pill tone={existing?.published ? 'green' : 'gray'}>{existing?.published ? '已發布' : '草稿'}</Pill></div><section className="simple-card journal-date-picker"><label>編輯日期<input type="date" value={selectedDate} onChange={(event) => setSelectedDate(event.target.value || today)} /></label><Button variant="outline" size="sm" onClick={() => setSelectedDate(today)}>回到今天</Button></section><JournalEditor key={selectedDate} data={data} updateData={updateData} selectedDate={selectedDate} existing={existing} />{history.length > 0 && <section className="simple-card journal-history"><div className="card-heading"><div><span className="kicker">紀錄</span><h2>過往聯絡簿</h2></div><Pill tone="gray">{history.length} 篇</Pill></div>{history.slice(0, 10).map((item) => <button key={item.id} className={cn(item.id === existing?.id && 'active')} onClick={() => setSelectedDate(item.date)}><span>{item.date}</span><strong>{item.homework || item.notice || item.bring || '聯絡簿內容'}</strong><Pill tone={item.published ? 'green' : 'gray'}>{item.published ? '已發布' : '草稿'}</Pill><ArrowRight size={14} /></button>)}</section>}</div>;
}

function TeacherHomework({ data, updateData, openScreen }: { data: AppData; updateData: (next: AppData) => void; openScreen: (homeworkId: string) => void }) {
  const [subject, setSubject] = useState(''); const [title, setTitle] = useState(''); const [publishOn, setPublishOn] = useState(today); const [due, setDue] = useState(''); const [attachmentsText, setAttachmentsText] = useState(''); const [formError, setFormError] = useState(''); const [query, setQuery] = useState(''); const [statusFilter, setStatusFilter] = useState<'全部' | '未完成' | '待核對' | '已完成'>('全部');
  const add = () => { if (!title.trim()) { setFormError('請輸入作業名稱。'); return; } const attachments = attachmentsText.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).map((line) => { const [name, ...urlParts] = line.split(/\s*\|\s*/); const url = urlParts.join('|').trim() || name.trim(); return { name: urlParts.length ? name.trim() : url, url }; }).filter((item) => /^https?:\/\//i.test(item.url)); setFormError(attachmentsText.trim() && attachments.length < attachmentsText.split(/\r?\n/).filter((line) => line.trim()).length ? '附件格式請使用「名稱 | https://網址」，並以一行一個連結。' : ''); if (attachmentsText.trim() && attachments.length === 0) return; const homework: Homework = { id: makeId('homework'), subject: subject.trim() || '作業', title: title.trim(), publishOn: publishOn.trim() || today, due: due.trim() || '未設定', attachments, screenReported: [], familyDone: [], teacherConfirmed: [] }; updateData({ ...data, homeworks: [...data.homeworks, homework] }); setSubject(''); setTitle(''); setPublishOn(today); setDue(''); setAttachmentsText(''); };
  const remove = (work: Homework) => { if (!window.confirm(`確定刪除「${work.title}」？相關登記也會一併移除。`)) return; updateData({ ...data, homeworks: data.homeworks.filter((item) => item.id !== work.id) }); };
  const confirm = (work: Homework, studentNumber: number) => { const reported = work.screenReported.includes(studentNumber) || work.familyDone.includes(studentNumber); if (!reported && !work.teacherConfirmed.includes(studentNumber)) return; const next = work.teacherConfirmed.includes(studentNumber) ? work.teacherConfirmed.filter((number) => number !== studentNumber) : [...work.teacherConfirmed, studentNumber]; updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, teacherConfirmed: next } : item) }); };
  const confirmAll = (work: Homework) => { const reported = [...new Set([...work.screenReported, ...work.familyDone])]; updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, teacherConfirmed: reported } : item) }); };
  const exportReport = () => { const rows = [['作業', '科目', '發布日', '截止日', '座號', '學生', '狀態']]; data.homeworks.forEach((work) => data.students.forEach((student) => rows.push([work.title, work.subject, work.publishOn || '立即', work.due, String(student.number), student.name, statusLabel(work, student.number)]))); downloadFile('班級作業統計.csv', rows.map((row) => row.map(csvEscape).join(',')).join('\n'), 'text/csv;charset=utf-8'); };
  const visible = data.homeworks.slice().reverse().filter((work) => { const matchesQuery = `${work.subject} ${work.title}`.toLowerCase().includes(query.trim().toLowerCase()); if (!matchesQuery) return false; if (statusFilter === '全部') return true; const registered = new Set([...work.screenReported, ...work.familyDone]).size; if (statusFilter === '未完成') return registered < data.students.length; if (statusFilter === '待核對') return registered > work.teacherConfirmed.length; return data.students.length > 0 && registered > 0 && work.teacherConfirmed.length >= data.students.length; });
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">作業</span><h1>建立與核對</h1><p>先輸入作業名稱與截止日；其他設定可以之後再補。</p></div><Button variant="outline" onClick={exportReport} disabled={!data.homeworks.length}><Download size={15} /> 匯出統計</Button></div><section className="simple-card add-form"><div className="quick-homework-form"><label className="homework-title-field">作業名稱<input value={title} onChange={(event) => { setTitle(event.target.value); setFormError(''); }} placeholder="例如：數學第 6 單元練習" /></label><label className="homework-due-field">截止日<input type="date" value={due} onChange={(event) => setDue(event.target.value)} /></label><Button onClick={add}><Plus size={15} /> 新增作業</Button></div><details className="homework-advanced"><summary><span>進階設定</span><small>科目、預約發布與附件</small></summary><div className="field advanced-homework-fields"><label>科目<input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="預設為「作業」" /></label><label>顯示日期<input type="date" value={publishOn} onChange={(event) => setPublishOn(event.target.value || today)} /></label></div><p className="inline-note schedule-note">顯示日期晚於今天時，作業會在指定日期自動出現在家長端與教室大螢幕。</p><label className="attachment-field"><span><Paperclip size={14} /> 附件或連結 <small>可選，每行一個：名稱 | https://網址</small></span><textarea value={attachmentsText} onChange={(event) => { setAttachmentsText(event.target.value); setFormError(''); }} placeholder={'講義 | https://drive.google.com/...\n影片 | https://youtu.be/...'} /></label></details>{formError && <p className="form-error">{formError}</p>}</section>{data.homeworks.length > 0 && <section className="simple-card homework-filters"><label className="search-field"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜尋科目或作業名稱" /></label><select aria-label="篩選作業狀態" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)}><option>全部</option><option>未完成</option><option>待核對</option><option>已完成</option></select><span className="filter-count">顯示 {visible.length} / {data.homeworks.length}</span></section>}{data.homeworks.length === 0 ? <section className="simple-card"><EmptyState icon={<CheckCircle2 size={20} />} title="還沒有作業" text="建立第一項作業後，就能開啟教室大螢幕。" /></section> : visible.length === 0 ? <section className="simple-card"><EmptyState icon={<Search size={20} />} title="找不到符合的作業" text="換個關鍵字或清除狀態篩選。" /></section> : <div className="work-list">{visible.map((work) => { const scheduled = !homeworkIsPublished(work); const registered = new Set([...work.screenReported, ...work.familyDone]); const canConfirmAll = registered.size > 0 && !scheduled; return <section className={cn('simple-card work-card', scheduled && 'scheduled-work')} key={work.id}><div className="work-head"><div><span className="subject-tag">{work.subject}</span><h2>{work.title}</h2><small>{scheduled ? `預約發布 ${work.publishOn}` : `已發布${work.publishOn ? ` ${work.publishOn}` : ''}`}・截止 {work.due}</small>{work.attachments?.length ? <div className="attachment-list">{work.attachments.map((attachment) => <a key={attachment.url} href={attachment.url} target="_blank" rel="noreferrer"><Link2 size={12} /> {attachment.name}</a>)}</div> : null}</div><div className="work-head-actions"><Button disabled={scheduled} onClick={() => openScreen(work.id)}><Grid2X2 size={15} /> {scheduled ? '尚未發布' : '開啟大螢幕'}</Button><Button variant="outline" size="sm" disabled={!canConfirmAll} onClick={() => confirmAll(work)}><ShieldCheck size={14} /> 全部核對</Button><Button variant="ghost" size="sm" aria-label={`刪除${work.title}`} onClick={() => remove(work)}><Trash2 size={14} /> 刪除</Button></div></div><div className="work-summary"><span>已登記 <strong>{registered.size}</strong> / {data.students.length}</span><span>教師確認 <strong>{work.teacherConfirmed.length}</strong></span><span>{scheduled ? `將於 ${work.publishOn} 顯示` : work.teacherConfirmed.length === data.students.length && data.students.length > 0 ? '全班完成' : registered.size > work.teacherConfirmed.length ? '有待核對' : '等待登記'}</span></div>{data.students.length ? <div className="student-check-grid">{data.students.map((student) => <button key={student.number} className={cn(work.teacherConfirmed.includes(student.number) && 'confirmed')} disabled={scheduled || (!registered.has(student.number) && !work.teacherConfirmed.includes(student.number))} onClick={() => confirm(work, student.number)}><strong>{String(student.number).padStart(2, '0')}</strong><span>{student.name}</span><small>{scheduled ? '尚未發布' : statusLabel(work, student.number)}</small></button>)}</div> : <p className="inline-note">請先到「班級」新增學生，才能追蹤繳交狀態。</p>}</section>; })}</div>}</div>;
}

function TeacherClass({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [number, setNumber] = useState(data.students.length ? String(Math.max(...data.students.map((student) => student.number)) + 1) : '1'); const [name, setName] = useState(''); const [bulk, setBulk] = useState(''); const [formError, setFormError] = useState(''); const [copied, setCopied] = useState(false);
  const add = () => { const parsed = Number(number); if (!name.trim()) { setFormError('請輸入學生姓名。'); return; } if (!Number.isInteger(parsed) || parsed < 1 || parsed > 999) { setFormError('座號請輸入 1 到 999 的整數。'); return; } if (data.students.some((student) => student.number === parsed)) { setFormError('這個座號已經存在。'); return; } setFormError(''); updateData({ ...data, students: [...data.students, { number: parsed, name: name.trim() }].sort((a, b) => a.number - b.number), inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); setName(''); setNumber(String(parsed + 1)); };
  const bulkAdd = () => { const rows = bulk.split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const additions: Student[] = []; for (const row of rows) { const [numberText, ...nameParts] = row.split(/[,，\t]/); const parsed = Number(numberText?.trim()); const studentName = nameParts.join(' ').trim(); if (!Number.isInteger(parsed) || parsed < 1 || parsed > 999 || !studentName || data.students.some((student) => student.number === parsed) || additions.some((student) => student.number === parsed)) { setFormError(`無法匯入「${row}」，格式請用：座號,姓名，且座號不可重複。`); return; } additions.push({ number: parsed, name: studentName }); } if (!additions.length) { setFormError('請先貼上至少一行學生資料。'); return; } setFormError(''); updateData({ ...data, students: [...data.students, ...additions].sort((a, b) => a.number - b.number), inviteCode: data.inviteCode || 'CLASS-' + Math.random().toString(36).slice(2, 7).toUpperCase() }); setBulk(''); };
  const copy = async () => { if (!data.inviteCode) return; try { await navigator.clipboard?.writeText(data.inviteCode); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setFormError('瀏覽器未允許複製，請手動選取邀請碼。'); } };
  const exportStudents = () => downloadFile('班級名單.csv', [['座號', '學生姓名'], ...data.students.map((student) => [String(student.number), student.name])].map((row) => row.map(csvEscape).join(',')).join('\n'), 'text/csv;charset=utf-8');
  const renameStudent = (student: Student) => { const nextName = window.prompt(`修改 ${String(student.number).padStart(2, '0')} 號姓名`, student.name)?.trim(); if (!nextName || nextName === student.name) return; updateData({ ...data, students: data.students.map((item) => item.number === student.number ? { ...item, name: nextName } : item) }); };
  const removeStudent = (numberToRemove: number, studentName: string) => { if (!window.confirm(`確定移除 ${String(numberToRemove).padStart(2, '0')} 號 ${studentName}？`)) return; updateData({ ...data, students: data.students.filter((student) => student.number !== numberToRemove), linkedChild: data.linkedChild === numberToRemove ? null : data.linkedChild, homeworks: data.homeworks.map((work) => ({ ...work, screenReported: work.screenReported.filter((number) => number !== numberToRemove), familyDone: work.familyDone.filter((number) => number !== numberToRemove), teacherConfirmed: work.teacherConfirmed.filter((number) => number !== numberToRemove) })), journals: data.journals.map((journal) => ({ ...journal, readByStudents: journal.readByStudents?.filter((number) => number !== numberToRemove), replies: Object.fromEntries(Object.entries(journal.replies || {}).filter(([key]) => key !== String(numberToRemove))) })) }); };
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">班級</span><h1>學生與家長連結</h1><p>學生只有座號資料，家長用邀請碼連結孩子。</p></div><Button variant="outline" onClick={exportStudents} disabled={!data.students.length}><Download size={15} /> 匯出名單</Button></div><section className="simple-card class-code-card"><div><span className="kicker">家長邀請碼</span><strong>{data.inviteCode || '新增第一位學生後產生'}</strong></div><Button variant="outline" size="sm" disabled={!data.inviteCode} onClick={() => void copy()}><Copy size={14} /> {copied ? '已複製' : '複製'}</Button></section><section className="simple-card add-student-card"><div className="field"><label>座號<input inputMode="numeric" value={number} onChange={(event) => { setNumber(event.target.value); setFormError(''); }} /></label><label>學生姓名<input value={name} onChange={(event) => { setName(event.target.value); setFormError(''); }} placeholder="輸入姓名" /></label><Button onClick={add}><Plus size={15} /> 新增學生</Button></div></section><section className="simple-card bulk-student-card"><div className="card-heading"><div><span className="kicker">快速匯入</span><h2>一次貼上名單</h2></div><FileText size={18} /></div><p>每行一位，格式：座號,姓名。也支援從試算表直接貼上。</p><textarea value={bulk} onChange={(event) => { setBulk(event.target.value); setFormError(''); }} placeholder={'1,王小明\n2,林小華'} /><Button variant="outline" onClick={bulkAdd}><Upload size={15} /> 匯入名單</Button>{formError && <p className="form-error">{formError}</p>}</section><section className="simple-card class-list-card"><div className="card-heading"><div><span className="kicker">班級名單</span><h2>{data.students.length} 位學生</h2></div></div>{data.students.length === 0 ? <EmptyState icon={<Users size={20} />} title="還沒有學生" text="先新增學生，接著把邀請碼給家長。" /> : <div className="student-list">{data.students.map((student) => <div key={student.number}><span className="number-badge">{String(student.number).padStart(2, '0')}</span><strong>{student.name}</strong><span>家長用班級邀請碼連結</span><Button variant="ghost" size="sm" onClick={() => renameStudent(student)}>修改</Button><Button variant="ghost" size="sm" onClick={() => removeStudent(student.number, student.name)}><X size={13} /> 移除</Button></div>)}</div>}</section></div>;
}

function ClassroomIntegration({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [courseName, setCourseName] = useState(data.classroomCourseName || ''); const [courseUrl, setCourseUrl] = useState(data.classroomUrl || ''); const [message, setMessage] = useState('');
  const connect = () => { const url = courseUrl.trim(); if (!url || !/^https?:\/\//i.test(url)) { setMessage('請貼上完整的 Google Classroom 課程網址。'); return; } updateData({ ...data, classroomCourseName: courseName.trim() || 'Google Classroom 課程', classroomUrl: url, classroomConnected: true }); setMessage('課程連結已儲存。'); };
  const disconnect = () => { updateData({ ...data, classroomCourseName: '', classroomUrl: '', classroomConnected: false }); setCourseName(''); setCourseUrl(''); setMessage('已移除課程連結。'); };
  return <section className="simple-card classroom-panel"><div className="card-heading"><div><span className="kicker">Google Classroom</span><h2><Link2 size={17} /> 課程連結整合</h2></div><Pill tone={data.classroomConnected ? 'green' : 'gray'}>{data.classroomConnected ? '已連結' : '尚未連結'}</Pill></div><p className="inline-note">先貼上課程連結，教師與家長可以快速開啟同一個 Classroom 課程。自動同步作業需要 Google OAuth 後端授權。</p><div className="field"><label>課程名稱<input value={courseName} onChange={(event) => setCourseName(event.target.value)} placeholder="五年三班 Classroom" /></label><label>課程網址<input type="url" value={courseUrl} onChange={(event) => setCourseUrl(event.target.value)} placeholder="https://classroom.google.com/..." /></label><Button onClick={connect}><Link2 size={14} /> 儲存連結</Button></div><div className="classroom-actions">{data.classroomConnected && <Button variant="outline" onClick={() => window.open(data.classroomUrl, '_blank', 'noopener,noreferrer')}><ExternalLink size={14} /> 開啟 Classroom</Button>}<Button variant="ghost" onClick={disconnect} disabled={!data.classroomConnected}>移除連結</Button></div>{message && <p className="form-message">{message}</p>}</section>;
}

function TeacherTools({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [seconds, setSeconds] = useState(15 * 60); const [running, setRunning] = useState(false); const [drawn, setDrawn] = useState<Student | null>(null); const [groupCount, setGroupCount] = useState(4); const [groups, setGroups] = useState<Student[][]>([]);
  useEffect(() => { if (!running) return; const timer = window.setInterval(() => setSeconds((value) => { if (value <= 1) { setRunning(false); return 0; } return value - 1; }), 1000); return () => window.clearInterval(timer); }, [running]);
  const draw = () => { if (!data.students.length) return; setDrawn(data.students[Math.floor(Math.random() * data.students.length)]); };
  const makeGroups = () => { const shuffled = [...data.students].sort(() => Math.random() - .5); const next = Array.from({ length: Math.max(1, Math.min(groupCount, shuffled.length || 1)) }, () => [] as Student[]); shuffled.forEach((student, index) => next[index % next.length].push(student)); setGroups(next); };
  const time = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">教學工具</span><h1>課堂小工具</h1><p>把計時、抽籤、分組與 Classroom 連結集中在同一頁。</p></div></div><ClassroomIntegration data={data} updateData={updateData} /><div className="tool-grid"><section className="simple-card tool-panel"><div className="tool-panel-head"><Clock3 size={18} /><h2>課堂計時器</h2></div><div className="timer-value">{time}</div><div className="timer-presets"><button onClick={() => setSeconds(5 * 60)}>05:00</button><button onClick={() => setSeconds(15 * 60)}>15:00</button><button onClick={() => setSeconds(25 * 60)}>25:00</button></div><div className="tool-actions"><Button onClick={() => setRunning((value) => !value)}>{running ? '暫停' : seconds === 0 ? '重新開始' : '開始'}</Button><Button variant="outline" onClick={() => { setRunning(false); setSeconds(15 * 60); }}><RotateCcw size={14} /> 重設</Button></div></section><section className="simple-card tool-panel"><div className="tool-panel-head"><Dices size={18} /><h2>隨機抽籤</h2></div><p className="tool-description">從目前班級名單抽出一位學生。</p><div className="draw-result">{drawn ? <><strong>{String(drawn.number).padStart(2, '0')}・{drawn.name}</strong><small>可以再抽一次</small></> : <><strong>尚未抽籤</strong><small>{data.students.length ? `目前有 ${data.students.length} 位學生` : '先到班級新增學生'}</small></>}</div><Button onClick={draw} disabled={!data.students.length}><Dices size={15} /> 抽一位</Button></section><section className="simple-card tool-panel"><div className="tool-panel-head"><Users size={18} /><h2>快速分組</h2></div><div className="group-control"><label>組數<input type="number" min="1" max={Math.max(1, data.students.length)} value={groupCount} onChange={(event) => setGroupCount(Number(event.target.value) || 1)} /></label><Button onClick={makeGroups} disabled={!data.students.length}>產生分組</Button></div>{groups.length ? <div className="group-result">{groups.map((group, index) => <div key={index}><strong>第 {index + 1} 組</strong><span>{group.map((student) => `${student.number} ${student.name}`).join('、')}</span></div>)}</div> : <p className="tool-description">依組數平均分配目前名單。</p>}</section></div></div>;
}

function AdminPanel({ view, data, updateData, go }: { view: AdminView; data: AppData; updateData: (next: AppData) => void; go: (view: AdminView) => void }) {
  const resetWorkspace = () => { if (!window.confirm('確定清除班級、作業、聯絡簿與行事曆？管理員帳號會保留。')) return; updateData({ ...emptyData, adminUsername: data.adminUsername, adminPasswordHash: data.adminPasswordHash }); };
  if (view === 'settings') return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">系統管理員</span><h1>資料管理</h1><p>管理目前裝置上的原型資料。</p></div><Button variant="outline" onClick={() => go('overview')}>回到總覽</Button></div><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">資料備份</span><h2><FileText size={17} /> 匯出完整工作區</h2></div><ShieldCheck size={18} /></div><p className="inline-note">備份包含班級名單、聯絡簿、作業、行事曆與帳號雜湊，可交給另一台裝置匯入。</p><Button onClick={() => downloadFile(`班級小本本管理備份-${getToday()}.json`, JSON.stringify(data, null, 2))}><Download size={14} /> 下載 JSON 備份</Button></section><section className="simple-card danger-panel"><div><strong><Trash2 size={16} /> 清除所有班級資料</strong><small>這會保留管理員帳號，但刪除目前工作區所有內容。</small></div><Button variant="outline" onClick={resetWorkspace}>清除資料</Button></section></div>;
  const publishedCount = data.journals.filter((journal) => journal.published).length;
  const registeredCount = data.homeworks.reduce((sum, work) => sum + new Set([...work.screenReported, ...work.familyDone]).size, 0);
  return <div className="workspace"><div className="workspace-head"><div><span className="kicker">系統管理員</span><h1>系統總覽</h1><p>快速確認目前班級工作區是否已準備好。</p></div><Button onClick={() => go('settings')}><Settings2 size={15} /> 資料管理</Button></div><div className="quick-grid"><button onClick={() => go('settings')}><span className="quick-icon peach"><Users size={19} /></span><strong>班級名單</strong><small>{data.students.length} 位學生</small></button><button onClick={() => go('settings')}><span className="quick-icon green"><BookOpen size={19} /></span><strong>聯絡簿</strong><small>{publishedCount} 篇已發布</small></button><button onClick={() => go('settings')}><span className="quick-icon blue"><CheckCircle2 size={19} /></span><strong>作業回報</strong><small>{registeredCount} 筆學生回報</small></button></div><div className="two-column"><section className="simple-card"><div className="card-heading"><div><span className="kicker">帳號狀態</span><h2><ShieldCheck size={17} /> 權限配置</h2></div><Pill tone="green">已啟用</Pill></div><div className="compact-list"><div><span>教師帳號</span><strong>{data.teacherUsername || '尚未設定'}</strong><Pill tone={data.teacherPasswordHash ? 'green' : 'gray'}>{data.teacherPasswordHash ? '可登入' : '待設定'}</Pill></div><div><span>家長帳號</span><strong>{data.familyUsername || '尚未建立'}</strong><Pill tone={data.familyPasswordHash ? 'green' : 'gray'}>{data.familyPasswordHash ? '可登入' : '待連結'}</Pill></div><div><span>管理員帳號</span><strong>{data.adminUsername}</strong><Pill tone="green">可登入</Pill></div></div></section><section className="simple-card"><div className="card-heading"><div><span className="kicker">儲存狀態</span><h2>目前工作區</h2></div></div><div className="compact-list"><div><span>班級</span><strong>{data.className || '尚未建立'}</strong></div><div><span>行事曆</span><strong>{data.events.length} 筆事件</strong></div><div><span>資料位置</span><strong>雲端資料庫（D1）</strong></div></div></section></div></div>;
}

function TeacherCalendar({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [eventTitle, setEventTitle] = useState(''); const [eventDate, setEventDate] = useState(''); const [eventType, setEventType] = useState<CalendarEvent['type']>('提醒'); const [eventError, setEventError] = useState('');
  const addEvent = () => { if (!eventTitle.trim() || !eventDate.trim()) { setEventError('請填寫日期與事件名稱。'); return; } setEventError(''); updateData({ ...data, events: [...data.events, { id: makeId('event'), title: eventTitle.trim(), date: eventDate.trim(), type: eventType }] }); setEventTitle(''); setEventDate(''); };
  const removeEvent = (event: CalendarEvent) => { if (!window.confirm(`確定移除「${event.title}」？`)) return; updateData({ ...data, events: data.events.filter((item) => item.id !== event.id) }); };
  const events = data.events.slice().sort((a, b) => a.date.localeCompare(b.date));
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">教師端</span><h1>班級行事曆</h1><p>活動、考試與提醒會同步顯示給家長。</p></div><Pill tone="blue">{events.length} 筆事件</Pill></div><section className="simple-card event-panel"><div className="card-heading"><div><span className="kicker">新增事件</span><h2>安排班級日程</h2></div><CalendarDays size={18} /></div><div className="field"><label>日期<input type="date" value={eventDate} onChange={(event) => { setEventDate(event.target.value); setEventError(''); }} /></label><label>事件名稱<input value={eventTitle} onChange={(event) => { setEventTitle(event.target.value); setEventError(''); }} placeholder="校外教學" /></label><label>類型<select value={eventType} onChange={(event) => setEventType(event.target.value as CalendarEvent['type'])}><option>提醒</option><option>活動</option><option>考試</option></select></label><Button onClick={addEvent}><Plus size={15} /> 新增</Button></div>{eventError && <p className="form-error">{eventError}</p>}</section><section className="simple-card calendar-panel"><div className="card-heading"><div><span className="kicker">班級日程</span><h2>接下來的安排</h2></div></div>{events.length ? <div className="event-list large">{events.map((event) => <div key={event.id}><span>{event.date}</span><strong>{event.title}</strong><Pill tone={event.type === '考試' ? 'orange' : 'blue'}>{event.type}</Pill><Button variant="ghost" size="sm" aria-label={`移除${event.title}`} onClick={() => removeEvent(event)}><Trash2 size={13} /> 移除</Button></div>)}</div> : <EmptyState icon={<CalendarDays size={20} />} title="還沒有班級事件" text="新增第一個活動後，家長端行事曆就會同步顯示。" />}</section></div>;
}

function TeacherSettings({ data, updateData }: { data: AppData; updateData: (next: AppData) => void }) {
  const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [accountMessage, setAccountMessage] = useState(''); const [fileMessage, setFileMessage] = useState(''); const fileRef = useRef<HTMLInputElement>(null);
  const changePassword = async () => { if (newPassword.trim().length < 4) { setAccountMessage('新密碼至少需要 4 個字元。'); return; } const currentHash = await hashSecret(currentPassword.trim()); if (data.teacherPasswordHash && currentHash !== data.teacherPasswordHash) { setAccountMessage('目前密碼不正確。'); return; } const nextHash = await hashSecret(newPassword.trim()); updateData({ ...data, teacherPassword: '', teacherPasswordHash: nextHash }); setCurrentPassword(''); setNewPassword(''); setAccountMessage('教師密碼已更新。'); };
  const exportBackup = () => downloadFile(`班級小本本備份-${getToday()}.json`, JSON.stringify(data, null, 2));
  const importBackup = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; file.text().then((text) => { try { const parsed = JSON.parse(text) as Partial<AppData>; if (!Array.isArray(parsed.students) || !Array.isArray(parsed.journals) || !Array.isArray(parsed.homeworks) || !Array.isArray(parsed.events)) throw new Error('format'); updateData({ ...emptyData, ...parsed }); setFileMessage('備份已匯入。'); } catch { setFileMessage('檔案格式不正確，請選擇班級小本本匯出的 JSON。'); } }).catch(() => setFileMessage('無法讀取備份檔案。')).finally(() => { if (fileRef.current) fileRef.current.value = ''; }); };
  const resetWorkspace = () => { if (!window.confirm('確定清除班級、作業、聯絡簿與行事曆？此動作無法復原。')) return; updateData({ ...emptyData, teacherUsername: data.teacherUsername, teacherPasswordHash: data.teacherPasswordHash }); setAccountMessage('工作區已清除，請重新建立班級。'); };
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">設定</span><h1>班級偏好</h1><p>帳號、資料備份與介面設定都集中在這裡。</p></div></div><section className="simple-card settings-panel"><div className="settings-row"><div><strong><Palette size={16} /> 主題色</strong><small>調整工作區的灰階層次。</small></div><div className="theme-picks"><button aria-label="深灰" className={cn('theme-pick coral', data.theme === 'coral' && 'active')} onClick={() => updateData({ ...data, theme: 'coral' })} /><button aria-label="中灰" className={cn('theme-pick blue', data.theme === 'blue' && 'active')} onClick={() => updateData({ ...data, theme: 'blue' })} /><button aria-label="淺灰" className={cn('theme-pick mint', data.theme === 'mint' && 'active')} onClick={() => updateData({ ...data, theme: 'mint' })} /></div></div><div className="settings-row"><div><strong><Grid2X2 size={16} /> 網格背景</strong><small>保留清楚的筆記本網格。</small></div><button aria-label="切換網格背景" aria-pressed={data.grid} className={cn('toggle', data.grid && 'on')} onClick={() => updateData({ ...data, grid: !data.grid })}><span /></button></div></section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">帳號操作</span><h2><LockKeyhole size={17} /> 更新教師密碼</h2></div><ShieldCheck size={18} /></div><div className="field"><label>目前密碼<input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>新密碼<input type="password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="至少 4 個字元" /></label><Button onClick={() => void changePassword()}><Save size={14} /> 更新密碼</Button></div>{accountMessage && <p className="form-message">{accountMessage}</p>}</section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">資料管理</span><h2>備份與還原</h2></div><FileText size={18} /></div><p className="inline-note">匯出檔案可以保存班級名單、聯絡簿、作業與行事曆，換裝置時再匯入。</p><div className="settings-actions"><Button variant="outline" onClick={exportBackup}><Download size={14} /> 匯出備份</Button><Button variant="outline" onClick={() => fileRef.current?.click()}><Upload size={14} /> 匯入備份</Button><input ref={fileRef} type="file" accept="application/json,.json" hidden onChange={importBackup} /></div>{fileMessage && <p className="form-message">{fileMessage}</p>}</section><section className="simple-card danger-panel"><div><strong><Trash2 size={16} /> 清除工作區</strong><small>保留教師帳號，刪除班級內所有資料。</small></div><Button variant="outline" onClick={resetWorkspace}>清除資料</Button></section></div>;
}

function FamilyCalendar({ data }: { data: AppData }) {
  const events = [...data.events, ...data.homeworks.filter((work) => homeworkIsPublished(work)).map((work) => ({ id: work.id, date: work.due, title: `${work.subject}・${work.title}`, type: '提醒' as const }))];
  return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">家長端</span><h1>行事曆</h1><p>查看班級活動與孩子作業期限。</p></div></div><section className="simple-card calendar-panel">{events.length ? <div className="event-list large">{events.sort((a, b) => a.date.localeCompare(b.date)).map((event) => <div key={event.id}><span>{event.date}</span><strong>{event.title}</strong><Pill tone={event.type === '考試' ? 'orange' : 'blue'}>{event.type}</Pill></div>)}</div> : <EmptyState icon={<CalendarDays size={20} />} title="還沒有行事曆內容" text="老師新增活動或作業期限後，會顯示在這裡。" />}</section></div>;
}

function FamilyView({ view, data, updateData }: { view: FamilyView; data: AppData; updateData: (next: AppData) => void }) {
  const [code, setCode] = useState(''); const [reply, setReply] = useState(''); const [selectedJournalId, setSelectedJournalId] = useState<string | null>(null); const [linkError, setLinkError] = useState(''); const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [accountMessage, setAccountMessage] = useState('');
  const child = data.students.find((student) => student.number === data.linkedChild);
  const link = () => { if (code.trim().toUpperCase() === data.inviteCode.toUpperCase() && data.students.length) { setLinkError(''); updateData({ ...data, linkedChild: data.students[0].number }); } else setLinkError('邀請碼不正確，請向老師確認。'); };
  if (!data.linkedChild || !child) return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">家長端</span><h1>先連結孩子</h1><p>請向老師索取班級邀請碼，輸入後就能看到聯絡簿。</p></div></div><section className="simple-card link-card"><label>班級邀請碼<input value={code} onChange={(event) => { setCode(event.target.value); setLinkError(''); }} placeholder="例如 CLASS-7F2P9" /></label><Button onClick={link} disabled={!data.inviteCode}>連結孩子 <ArrowRight size={15} /></Button>{linkError && <p className="form-error">{linkError}</p>}{!data.className && <p className="inline-note">老師尚未建立班級，請稍後再試。</p>}{data.className && !data.students.length && <p className="inline-note">老師已建立 {data.className}，但還沒有學生名單。</p>}</section></div>;
  const publishedJournals = data.journals.filter((item) => item.published).slice().sort((a, b) => b.date.localeCompare(a.date));
  const journal = publishedJournals.find((item) => item.id === selectedJournalId) || publishedJournals[0];
  const journalIsRead = journal ? journalReadBy(journal, child.number) : false;
  const childReply = journal ? journalReply(journal, child.number) : '';
  const setJournal = (next: Journal) => updateData({ ...data, journals: data.journals.map((item) => item.id === next.id ? next : item) });
  const publishedHomeworks = data.homeworks.filter((work) => homeworkIsPublished(work));
  if (view === 'homework') return <div className="workspace"><div className="workspace-head"><div><span className="kicker">家長端・{child.name}</span><h1>作業</h1><p>孩子可以在教室登記，家長也能回報已完成。</p></div></div><div className="family-work-list">{publishedHomeworks.length ? publishedHomeworks.map((work) => { const done = work.familyDone.includes(child.number); return <section className="simple-card family-work" key={work.id}><div><span className="subject-tag">{work.subject}</span><h2>{work.title}</h2><p>截止 {work.due}</p>{work.attachments?.length ? <div className="attachment-list">{work.attachments.map((attachment) => <a key={attachment.url} href={attachment.url} target="_blank" rel="noreferrer"><Link2 size={12} /> {attachment.name}</a>)}</div> : null}<Pill tone={work.teacherConfirmed.includes(child.number) ? 'green' : done ? 'orange' : 'gray'}>{statusLabel(work, child.number)}</Pill></div><Button variant={done ? 'outline' : 'default'} onClick={() => updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, familyDone: done ? item.familyDone.filter((number) => number !== child.number) : [...item.familyDone, child.number] } : item) })}>{done ? <><Check size={15} /> 已完成</> : '我做完了'}</Button></section>; }) : <section className="simple-card"><EmptyState icon={<CheckCircle2 size={20} />} title="目前沒有已發布作業" text="老師預約的作業會在顯示日期當天出現在這裡。" /></section>}</div></div>;
  if (view === 'calendar') return <FamilyCalendar data={data} />;
  if (view === 'me') { const changePassword = async () => { if (newPassword.trim().length < 4) { setAccountMessage('新密碼至少需要 4 個字元。'); return; } const currentHash = await hashSecret(currentPassword.trim()); if (data.familyPasswordHash && currentHash !== data.familyPasswordHash) { setAccountMessage('目前密碼不正確。'); return; } const nextHash = await hashSecret(newPassword.trim()); updateData({ ...data, familyPasswordHash: nextHash }); setCurrentPassword(''); setNewPassword(''); setAccountMessage('家長密碼已更新。'); }; return <div className="workspace narrow"><div className="workspace-head"><div><span className="kicker">我的帳號</span><h1>家庭設定</h1><p>目前連結：{child.name}・{data.className}</p></div></div><section className="simple-card"><div className="setting-line"><span>家庭邀請碼</span><strong>{data.inviteCode}</strong></div><div className="setting-line"><span>切換孩子</span><select aria-label="切換孩子" value={String(child.number)} onChange={(event) => updateData({ ...data, linkedChild: Number(event.target.value) })}>{data.students.map((student) => <option key={student.number} value={student.number}>{String(student.number).padStart(2, '0')} 號・{student.name}</option>)}</select></div><div className="setting-line"><span>資料保存</span><strong>雲端資料庫（D1）</strong></div></section><section className="simple-card account-panel"><div className="card-heading"><div><span className="kicker">帳號操作</span><h2><LockKeyhole size={17} /> 更新家長密碼</h2></div></div><div className="field"><label>目前密碼<input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>新密碼<input type="password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} placeholder="至少 4 個字元" /></label><Button onClick={() => void changePassword()}><Save size={14} /> 更新密碼</Button></div>{accountMessage && <p className="form-message">{accountMessage}</p>}</section></div>; }
  return <div className="workspace family-workspace"><div className="workspace-head"><div><span className="kicker">家長端・{child.name}</span><h1>聯絡簿</h1><p>{data.className}・座號 {String(child.number).padStart(2, '0')}</p></div><Pill tone={journalIsRead ? 'green' : 'orange'}>{journalIsRead ? '已確認閱讀' : '待確認閱讀'}</Pill></div>{journal ? <><section className="simple-card family-journal"><div className="journal-date">{journal.date}</div>{journal.homework && <div><h3><ClipboardCheck size={16} /> 今天的作業</h3><p>{journal.homework}</p></div>}{journal.bring && <div><h3><CalendarDays size={16} /> 明天要帶</h3><p>{journal.bring}</p></div>}{journal.notice && <div><h3><Bell size={16} /> 班級提醒</h3><p>{journal.notice}</p></div>}<div className="family-actions">{journalIsRead ? <span className="confirmed-line"><CheckCircle2 size={16} /> 已在本機記錄閱讀</span> : <Button onClick={() => setJournal({ ...journal, readBy: true, readByStudents: [...(journal.readByStudents || []), child.number] })}><Check size={15} /> 我已閱讀</Button>}</div></section><section className="simple-card reply-card"><h2><MessageCircle size={17} /> 回覆老師</h2>{childReply && <p className="sent-reply">上次回覆：{childReply}</p>}<textarea value={reply} onChange={(event) => setReply(event.target.value)} placeholder="例如：明天會帶齊觀察單，謝謝老師。" /><Button size="sm" disabled={!reply.trim()} onClick={() => { const nextReply = reply.trim(); setJournal({ ...journal, reply: nextReply, replies: { ...journal.replies, [String(child.number)]: nextReply } }); setReply(''); }}><Send size={14} /> 送出回覆</Button></section>{publishedJournals.length > 1 && <section className="simple-card journal-history"><div className="card-heading"><div><span className="kicker">紀錄</span><h2>過往聯絡簿</h2></div></div>{publishedJournals.filter((item) => item.id !== journal.id).slice(0, 5).map((item) => <button key={item.id} onClick={() => setSelectedJournalId(item.id)}><span>{item.date}</span><strong>{item.homework || item.notice || item.bring || '聯絡簿內容'}</strong><ArrowRight size={14} /></button>)}</section>}</> : <section className="simple-card"><EmptyState icon={<BookOpen size={20} />} title="老師還沒有發布今天的聯絡簿" text="發布後會在這裡看到作業、攜帶物品與班級提醒。" /></section>}</div>;
}

function Screen({ data, homeworkId, setRole, updateData }: { data: AppData; homeworkId: string | null; setRole: (role: Role) => void; updateData: (next: AppData) => void }) {
  const work = data.homeworks.find((item) => item.id === homeworkId) || data.homeworks[0];
  if (!work) return <div className="screen-empty"><h1>還沒有可登記的作業</h1><p>請先回到教師端建立作業。</p><Button onClick={() => setRole('teacher')}>回到教師端</Button></div>;
  if (!homeworkIsPublished(work)) return <div className="screen-empty"><h1>這份作業尚未發布</h1><p>預約發布日期：{work.publishOn}，日期到了才會開放學生登記。</p><Button onClick={() => setRole('teacher')}>回到教師端</Button></div>;
  return <main className="screen-view"><div className="screen-heading"><div><span className="kicker">{data.className}・教室大螢幕</span><h1>{work.subject}・{work.title}</h1><p>請點選自己的座號；完成後由教師核對。</p></div><div className="screen-count"><strong>{new Set([...work.screenReported, ...work.familyDone]).size}</strong><span>/ {data.students.length} 已登記</span></div></div><section className="screen-card"><div className="screen-instruction"><strong>點一下座號</strong><span>再點一次可以撤銷登記</span></div>{data.students.length ? <div className="screen-grid">{data.students.map((student) => { const selected = work.screenReported.includes(student.number); return <button key={student.number} className={cn(selected && 'selected')} onClick={() => updateData({ ...data, homeworks: data.homeworks.map((item) => item.id === work.id ? { ...item, screenReported: selected ? item.screenReported.filter((number) => number !== student.number) : [...item.screenReported, student.number] } : item) })}><strong>{String(student.number).padStart(2, '0')}</strong><span>{student.name}</span>{selected && <CheckCircle2 size={18} />}</button>; })}</div> : <EmptyState icon={<Users size={20} />} title="還沒有學生名單" text="請先回教師端新增學生。" />}<div className="screen-foot"><span>只顯示座號與登記狀態</span><Button variant="outline" onClick={() => setRole('teacher')}><X size={14} /> 結束</Button></div></section></main>;
}

export default function Home() {
  const [hydrated, setHydrated] = useState(false); const [loggedIn, setLoggedIn] = useState(false); const [role, setRole] = useState<Role>('teacher'); const [teacherView, setTeacherView] = useState<TeacherView>('home'); const [familyView, setFamilyView] = useState<FamilyView>('journal'); const [adminView, setAdminView] = useState<AdminView>('overview'); const [screenHomeworkId, setScreenHomeworkId] = useState<string | null>(null); const [data, setData] = useState<AppData>(emptyData); const [syncStatus, setSyncStatus] = useState<SyncStatus>('loading');
  const [, setDateTick] = useState(0); const databaseAvailable = useRef(false); const saveQueue = useRef<Promise<void>>(Promise.resolve());
  const persistToDatabase = (next: AppData) => {
    const task = saveQueue.current.then(async () => {
      const response = await fetch('/api/state', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ data: next }) });
      if (!response.ok) throw new Error('database-save-failed');
    });
    saveQueue.current = task.catch(() => undefined);
    return task;
  };
  useEffect(() => {
    let active = true;
    const loadWorkspace = async () => {
      let cached: AppData | null = null;
      try { const stored = window.localStorage.getItem(storageKey); if (stored) cached = { ...emptyData, ...JSON.parse(stored) }; } catch { cached = null; }
      try {
        const session = JSON.parse(window.localStorage.getItem(sessionKey) || 'null') as { role?: Role } | null;
        if (active && (session?.role === 'teacher' || session?.role === 'family' || session?.role === 'admin')) { setRole(session.role); setLoggedIn(true); }
      } catch { /* a missing session simply shows the login screen */ }
      try {
        const response = await Promise.race([
          fetch('/api/state', { cache: 'no-store' }),
          new Promise<Response>((_, reject) => window.setTimeout(() => reject(new Error('database-load-timeout')), 7000)),
        ]);
        if (!response.ok) throw new Error('database-load-failed');
        const result = await response.json() as { data?: Partial<AppData> | null };
        databaseAvailable.current = true;
        const remote = result.data && typeof result.data === 'object' ? { ...emptyData, ...result.data } : null;
        if (remote) { if (active) setData(remote); window.localStorage.setItem(storageKey, JSON.stringify(remote)); }
        else if (cached) { if (active) setData(cached); await persistToDatabase(cached); }
        if (active) setSyncStatus('database');
      } catch {
        databaseAvailable.current = false;
        if (active && cached) setData(cached);
        if (active) setSyncStatus('local');
      } finally {
        if (active) setHydrated(true);
      }
    };
    void loadWorkspace();
    return () => { active = false; };
  }, []);
  useEffect(() => { const timer = window.setInterval(() => setDateTick(Date.now()), 60_000); return () => window.clearInterval(timer); }, []);
  const updateData = (next: AppData) => {
    setData(next);
    window.localStorage.setItem(storageKey, JSON.stringify(next));
    if (!databaseAvailable.current) return;
    setSyncStatus('saving');
    void persistToDatabase(next).then(() => setSyncStatus('database')).catch(() => { databaseAvailable.current = false; setSyncStatus('local'); });
  };
  if (!hydrated) return <main className="loading-page"><Logo /><span>載入工作區…</span></main>;
  if (!loggedIn) return <Login data={data} updateData={updateData} onEnter={(nextRole, remember) => { setRole(nextRole); setLoggedIn(true); if (remember) window.localStorage.setItem(sessionKey, JSON.stringify({ role: nextRole })); }} />;
  const logout = () => { if (!window.confirm('確定要登出嗎？')) return; window.localStorage.removeItem(sessionKey); setLoggedIn(false); setRole('teacher'); };
  if (role === 'screen') return <><Topbar role={role} onRole={setRole} onLogout={logout} syncStatus={syncStatus} /><Screen data={data} homeworkId={screenHomeworkId} setRole={setRole} updateData={updateData} /></>;
  return <div className={cn('simple-app', `theme-${data.theme}`, data.grid ? 'with-grid' : 'no-grid')}><Topbar role={role} onRole={(nextRole) => { setRole(nextRole); }} onLogout={logout} syncStatus={syncStatus} /><Sidebar role={role} teacherView={teacherView} familyView={familyView} adminView={adminView} setTeacherView={setTeacherView} setFamilyView={setFamilyView} setAdminView={setAdminView} data={data} />{role === 'teacher' ? teacherView === 'home' ? <TeacherHome data={data} updateData={updateData} go={setTeacherView} /> : teacherView === 'journal' ? <TeacherJournal data={data} updateData={updateData} /> : teacherView === 'homework' ? <TeacherHomework data={data} updateData={updateData} openScreen={(id) => { setScreenHomeworkId(id); setRole('screen'); }} /> : teacherView === 'calendar' ? <TeacherCalendar data={data} updateData={updateData} /> : teacherView === 'class' ? <TeacherClass data={data} updateData={updateData} /> : teacherView === 'tools' ? <TeacherTools data={data} updateData={updateData} /> : <TeacherSettings data={data} updateData={updateData} /> : role === 'admin' ? <AdminPanel view={adminView} data={data} updateData={updateData} go={setAdminView} /> : <FamilyView view={familyView} data={data} updateData={updateData} />}</div>;
}



